    disc = float('inf')
    for coloring in product([-1, 1], repeat=ℓ):
        y = [sum(M[i][j] * coloring[j] for j in range(ℓ)) for i in range(len(D))]
        disc = min(disc, max(abs(y)))
    return disc

def compute_as(f):
    a = len(f)
    count = 0
    for x in product([0, 1], repeat=a):
        for y in product([0, 1], repeat=a):
